53-// Did a change to `file` touch only its comments? `before`/`after` are the file's
54-// two contents, null where it was added or deleted — neither of which is a
55-// comment-only change, whatever the other side holds.
56-//
57-// Indentation and blank lines are ignored, so a whitespace-only edit inside a
58-// template literal reads as comments-only; in a language whose indentation is
59-// semantic the extension set above has already answered no.
60-//
61-// Its callers grant a PERMISSION on the answer — may this run land its own pull
62-// request unreviewed, may it have touched this file at all — which is why the safe
63-// end is "no" and why the answer lives here rather than in each of them.
64-export function commentOnly(file, before, after) {
65-  if (before == null || after == null) return false;
66-  const dot = file.lastIndexOf('.');
67-  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
68:  if (!COMMENT_CHECKABLE.has(ext)) return false;
69-  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
70-  return meat(before) === meat(after);
71-}

